begin;
do $$
declare owner_id uuid; other_id uuid; a jsonb;b jsonb; before_events bigint;
begin
 select id into owner_id from public.ark60_students where username='rustam7';
 select id into other_id from public.ark60_students where username<>'rustam7' limit 1;
 if owner_id is null then raise exception 'owner missing';end if;
 select count(*) into before_events from public.ark60_coin_events;
 begin perform public.ark60_experience_action(other_id,'snapshot');raise exception 'non-owner accepted';exception when insufficient_privilege then null;end;
 a:=public.ark60_experience_action(owner_id,'reset','{"confirm":"RESET"}');
 if (a->>'wallet')::int<>1200 then raise exception 'initial balance';end if;
 a:=public.ark60_experience_action(owner_id,'buy','{"id":"forest","price":0}');
 b:=public.ark60_experience_action(owner_id,'buy','{"id":"forest"}');
 if (b->>'wallet')::int<>1050 or jsonb_array_length(b->'owned')<>1 then raise exception 'duplicate purchase';end if;
 begin perform public.ark60_experience_action(owner_id,'equip','{"id":"library"}');raise exception 'unowned accepted';exception when others then if sqlerrm not like '%EXPERIENCE_NOT_OWNED%' then raise;end if;end;
 a:=public.ark60_experience_action(owner_id,'equip','{"id":"forest"}');if a->'equipped'->>'theme'<>'forest' then raise exception 'equip';end if;
 a:=public.ark60_experience_action(owner_id,'review','{"id":"transport","answer":"1"}');
 perform public.ark60_experience_action(owner_id,'review','{"id":"transport","answer":"0"}');
 b:=public.ark60_experience_action(owner_id,'review','{"id":"transport","answer":"1"}');if a->>'wallet'<>b->>'wallet' then raise exception 'review farming';end if;
 a:=public.ark60_experience_action(owner_id,'review','{"id":"reliable","answer":" Reliable. "}');if not (a->'reviews'->'reliable'->>'correct')::boolean then raise exception 'answer whitespace punctuation';end if;
 a:=public.ark60_experience_action(owner_id,'task','{"id":"reading"}');b:=public.ark60_experience_action(owner_id,'task','{"id":"reading"}');if a->>'wallet'<>b->>'wallet' then raise exception 'task farming';end if;
 begin perform public.ark60_experience_action(owner_id,'claim_quest');raise exception 'early claim';exception when others then if sqlerrm not like '%EXPERIENCE_QUEST_INCOMPLETE%' then raise;end if;end;
 for i in 1..8 loop a:=public.ark60_experience_action(owner_id,'quest');end loop;if (a->>'quest')::int<>6 then raise exception 'quest overflow';end if;
 a:=public.ark60_experience_action(owner_id,'claim_quest');b:=public.ark60_experience_action(owner_id,'claim_quest');if a->>'wallet'<>b->>'wallet' then raise exception 'quest farming';end if;
 update public.ark60_experience_state set wallet=0 where student_id=owner_id;
 begin perform public.ark60_experience_action(owner_id,'buy','{"id":"library"}');raise exception 'negative wallet';exception when others then if sqlerrm not like '%EXPERIENCE_INSUFFICIENT_COINS%' then raise;end if;end;
 a:=public.ark60_experience_action(owner_id,'refill');if not a->'owned' ? 'forest' or (a->>'wallet')::int<>1200 then raise exception 'refill lost inventory';end if;
 a:=public.ark60_experience_action(owner_id,'clear','{"category":"theme"}');if a->'equipped' ? 'theme' then raise exception 'clear';end if;
 if (select count(*) from public.ark60_coin_events)<>before_events then raise exception 'real economy modified';end if;
 if has_table_privilege('anon','public.ark60_experience_state','SELECT') or has_table_privilege('authenticated','public.ark60_experience_state','UPDATE') or has_function_privilege('anon','public.ark60_experience_action(uuid,text,jsonb)','EXECUTE') then raise exception 'public access';end if;
 raise notice 'PASS owner isolation, prices, purchases, ownership, no farming, quest, balance and RLS';
end $$;
rollback;
